const GUMROAD_CHECKOUT_URL='https://gumroad.com/checkout?product=fywme&option=ArbuNBmxLE4TtR90oTUedg%3D%3D&quantity=1';function submitWaitlist(e){if(e)e.preventDefault();const i=document.getElementById('waitlistEmail'),f=document.querySelector('.waitlist-form'),b=document.getElementById('waitlistBtn');if(!i||!f)return;const m=i.value.trim(),r=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;if(!m||!r.test(m)){i.style.borderColor='#ef4444';i.placeholder='Por favor, introduce un email válido';i.value='';setTimeout(()=>{i.style.borderColor='rgba(212,175,55,0.3)';i.placeholder='tu@email.com'},2e3);return}const t=b.textContent;b.textContent='Redirigiendo...';b.disabled=true;if(typeof gtag!=='undefined')gtag('event','checkout_redirect',{event_category:'conversion',event_label:'DON Gumroad Checkout'});const u=encodeURIComponent(m);setTimeout(()=>{window.location.href=`${GUMROAD_CHECKOUT_URL}&email=${u}`},300)}document.addEventListener('DOMContentLoaded',function(){const i=document.getElementById('waitlistEmail');if(i)i.addEventListener('keypress',function(e){if(e.key==='Enter'){e.preventDefault();submitWaitlist()}});const btn=document.getElementById('preorderBtn'),pre=document.getElementById('preorder');function updateBtn(){const s=window.scrollY,d=document.documentElement.scrollHeight-window.innerHeight;if(s/d>.5)btn.classList.add('visible');else btn.classList.remove('visible')}window.addEventListener('scroll',updateBtn);updateBtn();btn.addEventListener('click',()=>pre.scrollIntoView({behavior:'smooth'}));const obs=new IntersectionObserver(e=>{e.forEach(n=>{if(n.isIntersecting)n.target.classList.add('visible')})},{threshold:.1});document.querySelectorAll('.fade-in').forEach(el=>obs.observe(el))});(function(){'use strict';const U=['utm_source','utm_medium','utm_campaign','utm_term','utm_content'];function getUTM(){const p=new URLSearchParams(window.location.search),u={};U.forEach(k=>{const v=p.get(k);if(v)u[k]=v});const l=window.currentLanguage||localStorage.getItem('userLanguage')||document.documentElement.lang||'en';if(u.utm_content){if(!u.utm_content.includes('_lang-'))u.utm_content+='_lang-'+l}else if(Object.keys(u).length>0)u.utm_content='lang-'+l;return u}function appendUTM(url,u){if(!Object.keys(u).length)return url;try{const o=new URL(url);Object.entries(u).forEach(([k,v])=>o.searchParams.set(k,v));return o.toString()}catch(e){return url}}function updateLinks(){const u=getUTM();if(!Object.keys(u).length)return;document.querySelectorAll('a[href*="gumroad.com"]').forEach(a=>{a.setAttribute('href',appendUTM(a.getAttribute('href'),u))})}window.getStoredUTMParams=function(){try{return JSON.parse(sessionStorage.getItem('utm_params'))||{}}catch(e){return{}}};window.buildGumroadUrl=function(b){return appendUTM(b,window.getStoredUTMParams())};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',updateLinks);else updateLinks();document.addEventListener('translationsLoaded',updateLinks)})();
